<?php
require_once __DIR__.'/../../app/layout.php';
$u=require_login('admin');
$stats=db()->query("SELECT COUNT(*) AS total, SUM(status='pending') AS pending_count, SUM(status='approved') AS approved_count, SUM(status='printing') AS printing_count, SUM(status='ready') AS ready_count FROM print_orders")->fetch();
$today=db()->query('SELECT COALESCE(SUM(amount),0) FROM payments WHERE DATE(paid_at)=CURDATE()')->fetchColumn();
$queue=db()->query("SELECT o.id,o.order_no,o.status,o.total_price,o.created_at,u.full_name AS customer_name,f.original_name FROM print_orders o JOIN users u ON u.id=o.customer_id JOIN order_files f ON f.order_id=o.id WHERE o.status IN ('pending','approved','printing','ready') ORDER BY FIELD(o.status,'pending','approved','printing','ready'),o.created_at ASC LIMIT 10")->fetchAll();
page_header('Dashboard','admin/dashboard.php','Here’s a quick look at your printing queue.'); ?>
<div class="admin-intro"><div><span class="eyebrow">ADMIN OVERVIEW</span><h2>Stay on top of every order.</h2><p>Review incoming requests and keep printing moving.</p></div><a class="btn btn-primary" href="<?=e(url('admin/orders.php'))?>"><?=svg_icon('file')?> Manage orders</a></div>
<div class="stats-grid four"><div class="stat-card"><span class="stat-icon amber"><?=svg_icon('clock')?></span><div><div class="stat-number"><?= (int)($stats['pending_count']??0) ?></div><div class="stat-label">Needs approval</div></div></div><div class="stat-card"><span class="stat-icon blue"><?=svg_icon('check')?></span><div><div class="stat-number"><?= (int)($stats['approved_count']??0) ?></div><div class="stat-label">Approved</div></div></div><div class="stat-card"><span class="stat-icon purple"><?=svg_icon('printer')?></span><div><div class="stat-number"><?= (int)($stats['printing_count']??0) ?></div><div class="stat-label">Printing</div></div></div><div class="stat-card"><span class="stat-icon teal"><?=svg_icon('check')?></span><div><div class="stat-number"><?= (int)($stats['ready_count']??0) ?></div><div class="stat-label">Awaiting pickup</div></div></div></div>
<div class="metrics-strip"><span><?=svg_icon('tag')?> Cash collected today</span><strong><?=money($today)?></strong><span class="metric-note">Completed payments only</span></div>
<section class="panel"><div class="section-top"><div><h2>Processing queue</h2><p>Open requests requiring action</p></div><a class="text-link" href="<?=e(url('admin/orders.php'))?>">All orders <?=svg_icon('arrow')?></a></div><?php if(!$queue):?><div class="empty-state"><span class="empty-icon"><?=svg_icon('check')?></span><h3>All caught up!</h3><p>No requests are waiting for action.</p></div><?php else:?><div class="table-wrap"><table><thead><tr><th>ORDER / FILE</th><th>CUSTOMER</th><th>AMOUNT</th><th>STATUS</th><th></th></tr></thead><tbody><?php foreach($queue as $r):?><tr><td><strong><?=e($r['order_no'])?></strong><div class="secondary-line"><?=e($r['original_name'])?></div></td><td><?=e($r['customer_name'])?></td><td class="price-cell"><?=money($r['total_price'])?></td><td><?=status_badge($r['status'])?></td><td><a class="table-action" href="<?=e(url('admin/order.php?id='.$r['id']))?>">Manage <?=svg_icon('arrow')?></a></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<?php page_footer(); ?>
